// Basic HTML parsing — Wellfound requires login for full data.
// This extracts structured-data JSON-LD blocks if present.
const raw = $input.all()[0]?.json?.data || '';
const results = [];
const jsonLdRegex = /<script type="application\/ld\+json">(.*?)<\/script>/gsi;
let match;
while ((match = jsonLdRegex.exec(raw)) !== null) {
  try {
    const obj = JSON.parse(match[1]);
    if (obj['@type'] === 'JobPosting') {
      results.push({
        json: {
          job_title: obj.title || '',
          company: obj.hiringOrganization?.name || '',
          job_url: obj.url || obj.sameAs || '',
          source: 'Wellfound',
          location_text: (obj.jobLocation?.address?.addressCountry || 'remote').toLowerCase(),
          salary: obj.baseSalary?.value?.value ? `${obj.baseSalary.value.value} ${obj.baseSalary.currency}` : '',
          description: (obj.description || '').replace(/<[^>]*>/g, ' ').trim().slice(0, 2000),
          posted_date: obj.datePosted || new Date().toISOString(),
          tags: '',
          job_id: `wellfound_${Buffer.from(obj.url || obj.title || '').toString('base64').slice(0, 16)}`
        }
      });
    }
  } catch (e) {}
}
return results.length ? results : [];

