  'machine learning', 'junior data'
];

return $input.all().filter(item => {
  const searchText = [
    item.json.job_title,
    item.json.description,
    item.json.tags
  ].join(' ').toLowerCase();
  return KEYWORDS.some(kw => searchText.includes(kw.toLowerCase()));
});

// Build set of existing job URLs and company+title combos from sheet
const allItems = $input.all();

// Items from node 'Read Existing Jobs Sheet' come in via $('Read Existing Jobs Sheet').all()
// We use context: first batch = new jobs, second = sheet data
// In n8n this node receives new jobs; sheet data comes from the previous node in the chain.
// We need to restructure as a merge — see connections.

// This node receives the MERGED output: [newJobs..., sheetJobs...]
// We split by checking if item has 'job_url' (new) vs 'job_url' from sheet
const newJobs = $('Keyword Filter').all();
const existingRows = $('Read Existing Jobs Sheet').all();

const existingUrls = new Set(existingRows.map(r => (r.json.job_url || '').trim()).filter(Boolean));
const existingKeys = new Set(
  existingRows.map(r => `${(r.json.company || '').toLowerCase()}::${(r.json.job_title || '').toLowerCase()}`)
);

return newJobs.filter(item => {
  const url = (item.json.job_url || '').trim();
  const key = `${(item.json.company || '').toLowerCase()}::${(item.json.job_title || '').toLowerCase()}`;
  if (!url) return false;
  if (existingUrls.has(url)) return false;
  if (existingKeys.has(key)) return false;
  return true;
});

const REJECT_PATTERNS = [
  /\bus only\b/i, /\busa only\b/i, /\bunited states only\b/i,
  /\bcanada only\b/i, /\bcadanian only\b/i,
  /\buk only\b/i, /\bunited kingdom only\b/i,
  /\beu only\b/i, /\beurope only\b/i, /\beuropean union only\b/i,
  /\baustralia only\b/i, /\baustralian only\b/i,
  /\bmust be based in\b/i, /\bmust live in\b/i,
  /\bmust be located in\b/i, /\bmust reside in\b/i,
  /\bmust be authorized to work in\b/i,
  /\bwork authorization\b.*\b(us|uk|eu|canada|australia)\b/i,
  /\blocal work permit required\b/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i,
  /\boffice required\b/i, /\bin-office\b/i,
  /\bremote within [a-z]+ only\b/i, /\bremote within the us\b/i,
  /\bfixed us hours\b/i, /\bfixed eu hours\b/i,
  /\bcst only\b/i, /\best only\b/i, /\bpst only\b/i,
  /\brelocate\b/i,
  /\bwork visa\b.*\bsponsored?\b/i,
  /\bopen to.*us.*only\b/i
];

const KEEP_SIGNALS = [
  /worldwide remote/i, /global remote/i, /work from anywhere/i,
  /anywhere in the world/i, /apac remote/i,
  /international contractors?/i, /\bcontractor\b/i, /\bb2b\b/i,
  /\bdeel\b/i, /\bremote\.com\b/i, /\boyster\b/i, /\beor\b/i,
  /employer of record/i, /remote.?first/i, /distributed team/i
];

return $input.all().map(item => {
  const text = [
    item.json.job_title,
    item.json.description,
    item.json.location_text,
    item.json.tags
  ].join(' ');

  const rejected = REJECT_PATTERNS.some(p => p.test(text));
  const hasKeepSignal = KEEP_SIGNALS.some(p => p.test(text));

  if (rejected && !hasKeepSignal) return null;

  return {
    json: {
      ...item.json,
      hard_filter_passed: true,
      has_keep_signal: hasKeepSignal
    }
  };
}).filter(Boolean);

