const aiText = $json.message?.content || $json.choices?.[0]?.message?.content || '{}';
let aiResult = {};
try {
  const cleaned = aiText.replace(/```json\n?|```\n?/g, '').trim();
  aiResult = JSON.parse(cleaned);
} catch (e) {
  aiResult = {
    taiwan_eligible: 'unclear',
    reason: 'Parse error',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };
}

// Merge AI result back with the original job data
const originalJob = $('Batch Jobs for AI').item.json;

return {
  json: {
    ...originalJob,
    taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
    taiwan_reason: aiResult.reason || '',
    location_risk: aiResult.location_risk || 'medium',
    timezone_risk: aiResult.timezone_risk || 'medium',
    contractor_possible: aiResult.contractor_possible || 'unclear',
    ai_decision: aiResult.decision || 'manual_check'
  }
};

const ASYNC_KEEP = [
  /\basync\b/i, /\basynchronous\b/i,
  /flexible hours/i, /flexible schedule/i,
  /distributed team/i, /remote.?first/i,
  /low meeting/i, /work across time zones/i,
  /no set hours/i, /results.?oriented/i,
  /work when you want/i, /own your schedule/i
];

const ASYNC_REJECT = [
  /strict 9.?to.?5/i, /9am.?5pm/i,
  /fixed (us|est|pst|cet|gmt) hours/i,
  /daily (standup|live|video) call/i,
  /must overlap full business day/i,
  /must be online.{0,30}(est|pst|cet|9am|8am)/i
];

const text = [$json.description, $json.tags, $json.job_title].join(' ');

const asyncMatches = ASYNC_KEEP.filter(p => p.test(text)).map(p => p.source);
const syncFlags = ASYNC_REJECT.filter(p => p.test(text));

if (syncFlags.length > 0 && asyncMatches.length === 0) return null;

let asyncLevel = 'unknown';
if (asyncMatches.length >= 3) asyncLevel = 'high';
else if (asyncMatches.length >= 1) asyncLevel = 'medium';
else asyncLevel = 'low';

return {
  json: {
    ...$json,
    async_level: asyncLevel,
    async_signals: asyncMatches.join(', ')
  }
};

const text = [$json.description, $json.job_title, $json.tags].join(' ').toLowerCase();

// --- Role categorization ---
const ROLES_PRIMARY = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence', 'bi analyst', 'marketing analyst',
  'performance marketing analyst', 'growth analyst',
  'ai marketing', 'ai automation', 'ai workflow',
  'creative strategist with data', 'martech analyst',
  'analytics engineer', 'marketing data'
];
const ROLES_ADJACENT = [
  'digital marketing', 'seo', 'ppc', 'growth hacker',
  'content analyst', 'product analyst', 'operations analyst',
  'revenue operations', 'demand generation', 'crm analyst'
];

let roleCategory = 'other';
let roleScore = 0;
if (ROLES_PRIMARY.some(r => text.includes(r))) {
  roleCategory = 'primary';
  roleScore = 25;
} else if (ROLES_ADJACENT.some(r => text.includes(r))) {
  roleCategory = 'adjacent';
  roleScore = 15;
}

// --- Taiwan eligibility score ---
let taiwanScore = 0;
const twEl = ($json.taiwan_eligible || '').toLowerCase();
const locRisk = ($json.location_risk || 'high').toLowerCase();
const twText = text;
if (
  twEl === 'yes' ||
  /worldwide|work from anywhere|global remote|international contractor|anywhere/i.test(twText)
) {
  taiwanScore = 40;
} else if (/apac/i.test(twText) || locRisk === 'low') {
  taiwanScore = 30;
} else if (twEl === 'unclear' && locRisk !== 'high') {
  taiwanScore = 20;
} else {
  taiwanScore = 0;
}

// --- Async score ---
let asyncScore = 0;
const asyncLvl = ($json.async_level || 'unknown').toLowerCase();
if (asyncLvl === 'high' || /clearly async|async work/i.test(text)) asyncScore = 25;
else if (asyncLvl === 'medium' || /flexible hours/i.test(text)) asyncScore = 20;
else if (/distributed team/i.test(text)) asyncScore = 15;
else if (/remote.?first/i.test(text)) asyncScore = 10;

// --- Salary score ---
let salaryScore = 0;
const salaryRaw = ($json.salary || '').replace(/,/g, '');
const salaryNums = salaryRaw.match(/\d+/);
if (salaryNums) {
  const num = parseInt(salaryNums[0]);
  const isAnnual = num > 50000;
  const monthly = isAnnual ? Math.round(num / 12) : num;
  if (monthly >= 5000) salaryScore = 25;
  else if (monthly >= 3000) salaryScore = 15;
  else salaryScore = 10;
} else if (salaryRaw.length > 2) {
  salaryScore = 10;
}

const totalScore = Math.min(100, taiwanScore + asyncScore + roleScore + salaryScore);

// --- Why good fit (brief) ---
const reasons = [];
if (taiwanScore >= 30) reasons.push('Taiwan-eligible');
if (asyncScore >= 20) reasons.push('async-friendly');
if (roleScore === 25) reasons.push('target role match');
if (salaryScore >= 15) reasons.push('good salary');
const whyGoodFit = reasons.join(', ') || 'needs manual review';

return {
  json: {
    ...$json,
    score: totalScore,
    role_category: roleCategory,
    why_good_fit: whyGoodFit,
    decision: totalScore >= 85 ? 'apply_now' : totalScore >= 70 ? 'save' : 'reject'
  }
};

