parameters.jsCode:
const jobs = $input.all()[0]?.json?.data || [];

const sorted = [...jobs].sort((a, b) => (b.score || 0) - (a.score || 0));
const topJobs = sorted.filter(j => j.ai_decision !== 'reject' && j.score >= 70);
const manualCheck = sorted.filter(j => j.taiwan_eligible === 'unclear' && j.score >= 70);

// Rejection stats
const allRaw = jobs;
const rejectedUS = allRaw.filter(j => /us only|usa only|united states only/i.test(j.description || '')).length;
const rejectedEU = allRaw.filter(j => /eu only|europe only/i.test(j.description || '')).length;
const rejectedHybrid = allRaw.filter(j => /hybrid|onsite|on-site/i.test(j.description || '')).length;
const rejectedTZ = allRaw.filter(j => j.timezone_risk === 'high').length;

// Format top jobs
const topSection = topJobs.slice(0, 10).map((j, i) => {
  return `<div style="border-left:4px solid ${j.score >= 85 ? '#e53935' : '#1a73e8'};padding:12px;margin-bottom:16px;background:#fafafa">
    <h3>${i + 1}. ${j.job_title}</h3>
    <table style="border-collapse:collapse;font-size:14px">
      <tr><td style="padding:3px 8px;font-weight:bold">Company</td><td style="padding:3px 8px">${j.company}</td></tr>
      <tr><td style="padding:3px 8px;font-weight:bold">Score</td><td style="padding:3px 8px">${j.score}/100${j.score >= 85 ? ' 🔴 APPLY NOW' : ''}</td></tr>
      <tr><td style="padding:3px 8px;font-weight:bold">Taiwan Eligible</td><td style="padding:3px 8px">${j.taiwan_eligible}</td></tr>
      <tr><td style="padding:3px 8px;font-weight:bold">Reason</td><td style="padding:3px 8px">${j.taiwan_reason || '-'}</td></tr>
      <tr><td style="padding:3px 8px;font-weight:bold">Async Level</td><td style="padding:3px 8px">${j.async_level}</td></tr>
      <tr><td style="padding:3px 8px;font-weight:bold">Timezone Risk</td><td style="padding:3px 8px">${j.timezone_risk}</td></tr>
      <tr><td style="padding:3px 8px;font-weight:bold">Salary</td><td style="padding:3px 8px">${j.salary || 'Not listed'}</td></tr>
      <tr><td style="padding:3px 8px;font-weight:bold">Why It Fits Jerry</td><td style="padding:3px 8px">${j.why_good_fit}</td></tr>
    </table>
    <a href="${j.job_url}" style="display:inline-block;margin-top:8px;background:#1a73e8;color:#fff;padding:6px 16px;text-decoration:none;border-radius:3px">Apply</a>
  </div>`;
}).join('\n');

// Manual check section
const manualSection = manualCheck.length > 0
  ? `<h2>Manual Check Required</h2><ul>${manualCheck.map(j =>
      `<li><strong>${j.job_title}</strong> at ${j.company} — Score: ${j.score} | Location Risk: ${j.location_risk} — <a href="${j.job_url}">View</a></li>`
    ).join('')}</ul>`
  : '<p>No manual checks today.</p>';

const html = `
<div style="font-family:sans-serif;max-width:800px;margin:0 auto">
  <h1 style="color:#1a73e8">Daily Taiwan Eligible Async Remote Jobs</h1>
  <p style="color:#666">${new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric', timeZone:'Asia/Taipei' })} — Taiwan Time</p>
  <p><strong>${topJobs.length}</strong> jobs passed all filters today. <strong>${topJobs.filter(j => j.score >= 85).length}</strong> are priority applies.</p>
  <h2>Top Jobs Today</h2>
  ${topSection || '<p>No qualifying jobs found today.</p>'}
  ${manualSection}
  <h2>Rejection Summary</h2>
  <ul>
    <li>US only: ${rejectedUS}</li>
    <li>EU only: ${rejectedEU}</li>
    <li>Hybrid/Onsite: ${rejectedHybrid}</li>
    <li>Timezone risk: ${rejectedTZ}</li>
  </ul>
  <p style="color:#999;font-size:12px">Generated by Daily Taiwan Eligible Async Remote Job Hunter</p>
</div>
`;

return [{ json: { html, total_jobs: topJobs.length, priority_count: topJobs.filter(j => j.score >= 85).length } }];
